-- Server-only secrets (PIN pepper, Web Push keys). Generated by the edge
-- functions on first use. RLS on with no policies: only the service role can read.
create table public.app_secrets (
  key   text primary key,
  value text not null,
  created_at timestamptz not null default now()
);
alter table public.app_secrets enable row level security;
revoke all on public.app_secrets from anon, authenticated;
grant all on public.app_secrets to service_role;

-- Phone notifications: each new notification is handed to the push-notify
-- edge function. settings.push_url holds that function's URL.
alter table public.notifications add column pushed_at timestamptz;
alter table public.settings add column push_url text;

do $$ begin
  create extension if not exists pg_net;
exception when others then
  raise notice 'pg_net not available (%): phone notifications will not be sent', sqlerrm;
end $$;

create or replace function public._push_notification() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_url text;
begin
  select push_url into v_url from settings where id = 1;
  if v_url is not null then
    begin
      perform net.http_post(url := v_url, body := jsonb_build_object('id', new.id),
                            headers := '{"Content-Type": "application/json"}'::jsonb);
    exception when others then
      null;  -- never block the action that raised the notification
    end;
  end if;
  return new;
end $$;
revoke execute on function public._push_notification() from public, anon, authenticated;

create trigger notifications_push after insert on public.notifications
  for each row execute function public._push_notification();
